const sources={muertos:'https://commons.wikimedia.org/wiki/File:Gran_Desfile_del_D%C3%ADa_de_Muertos_(tambores_entre_El_Caballito_y_avenida_Ju%C3%A1rez).jpg',condesa:'https://commons.wikimedia.org/wiki/File:Condesa_Mexico_City_neighborhood_main_street_jacaranda_flowering.jpg',margarita:'https://www.locotequila.mx/margarita-al-pastor'};
export function initHighlights({open,esc,onExplore}){
const root=document.querySelector('#featured');let index=0;
const slides=[
{id:'muertos',image:'assets/banner-muertos.jpg',label:'ESPECIAL DE TEMPORADA',title:'El color de nuestras tradiciones',summary:'Día de Muertos · Memorias de la ciudad',cta:'Ver especial',action:'season',credit:'Milton Martínez / Secretaría de Cultura CDMX · Archivo 2023'},
{id:'condesa',image:'assets/banner-condesa.jpg',label:'EL BARRIO A TU RITMO',title:'Piérdete un rato en Condesa',summary:'Terrazas, mesas y nuevas esquinas.',cta:'Explorar planes',action:'explore',credit:'Lazjak · Wikimedia Commons · Archivo 2023'},
{id:'margarita',image:'assets/margarita.webp',label:'PROMOCIÓN DEMO',title:'Una margarita y un nuevo plan',summary:'15% de ejemplo en Licorería Limantour.',cta:'Ver cupón',action:'coupon',credit:'Ignacio Urquiza / Loco Tequila'}];
root.innerHTML=`<div class="featured-slides">${slides.map((s,i)=>`<article class="featured-slide ${s.id}" ${i?'hidden':''} aria-label="${esc(s.title)}"><img src="${s.image}" alt="${esc(s.id==='muertos'?'Participantes del desfile de Día de Muertos en Ciudad de México, 2023':s.id==='condesa'?'Una calle de Condesa con jacarandas, fotografía de archivo de marzo de 2023':'Margarita al pastor de Licorería Limantour')}" width="1600" height="650" loading="${i?'lazy':'eager'}" fetchpriority="${i?'low':'high'}"><div class="featured-shade"></div><div class="featured-copy"><p class="featured-label">${s.label}</p><h2>${s.title}</h2><p class="featured-summary">${s.summary}</p><button class="featured-cta" ${s.action==='coupon'?'data-coupon="limantour"':`data-highlight-action="${s.action}"`}>${s.cta} ↗</button></div><button class="featured-credit" data-highlight-credit="${s.id}" aria-label="Créditos de la imagen">© ${s.credit}</button></article>`).join('')}</div><div class="featured-navigation"><button id="featured-prev" aria-label="Destacado anterior">←</button><div class="featured-dots" aria-label="Seleccionar destacado">${slides.map((s,i)=>`<button data-highlight-index="${i}" aria-label="${esc(s.title)}" aria-pressed="${i===0}"><span class="sr-only">${i+1}</span></button>`).join('')}</div><span id="featured-status" aria-live="polite">1 / 3</span><button id="featured-next" aria-label="Siguiente destacado">→</button></div>`;
function show(next){index=(next+slides.length)%slides.length;root.querySelectorAll('.featured-slide').forEach((s,i)=>s.hidden=i!==index);root.querySelectorAll('[data-highlight-index]').forEach((b,i)=>b.setAttribute('aria-pressed',i===index));document.querySelector('#featured-status').textContent=`${index+1} / ${slides.length}`;}
function credits(id){const s=slides.find(s=>s.id===id);open(`<p class="eyebrow">${id==='muertos'?'DÍA DE MUERTOS · ARCHIVO 2023':'FOTOGRAFÍA DEL BARRIO'}</p><h2 id="dialog-title">${id==='muertos'?'Día de Muertos':id==='condesa'?'Una mirada a Condesa':'Margarita al pastor'}</h2><img class="feature-detail-image" src="${s.image}" alt="${esc(s.title)}"><p>${id==='muertos'?'Fotografía del desfile de Día de Muertos del 4 de noviembre de 2023 en Ciudad de México. Un especial editorial de temporada; no es un próximo evento ni una reserva.':id==='condesa'?'Una calle de Condesa con jacarandas, fotografiada en marzo de 2023. Imagen de archivo para inspirar tu siguiente paseo.':'Fotografía de la Margarita al Pastor de Limantour, publicada por Loco Tequila. El descuento La Vita es ficticio y no puede canjearse.'}</p><p class="small">${s.credit}. ${id==='muertos'?'Se ajustó el tamaño de la imagen; el banner muestra un encuadre mediante CSS.':id==='condesa'?'Se ajustó el tamaño; encuadre del banner mediante CSS.':''}</p><div class="links"><a href="${sources[id]}" target="_blank" rel="noopener noreferrer">Fuente de la fotografía ↗</a>${id!=='margarita'?`<a href="https://creativecommons.org/licenses/${id==='muertos'?'by/2.0':'by-sa/4.0'}/" target="_blank" rel="noopener noreferrer">${id==='muertos'?'CC BY 2.0':'CC BY-SA 4.0'} ↗</a>`:''}</div>`);}
root.querySelector('#featured-prev').onclick=()=>show(index-1);root.querySelector('#featured-next').onclick=()=>show(index+1);
root.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1));};
root.addEventListener('click',e=>{const dot=e.target.closest('[data-highlight-index]');if(dot)show(Number(dot.dataset.highlightIndex));const credit=e.target.closest('[data-highlight-credit]');if(credit)credits(credit.dataset.highlightCredit);const action=e.target.closest('[data-highlight-action]');if(action?.dataset.highlightAction==='season')credits('muertos');if(action?.dataset.highlightAction==='explore')onExplore();});
let start;root.addEventListener('touchstart',e=>{start=e.touches[0].clientX;},{passive:true});root.addEventListener('touchend',e=>{if(start===undefined)return;const dx=e.changedTouches[0].clientX-start;if(Math.abs(dx)>55)show(index+(dx<0?1:-1));start=undefined;},{passive:true});
}
